/// <summary>
/// Checks if site exists or not.
/// </summary>
/// <param name = "_siteId">Site Id.</param>
/// <returns>True if exists; otherwise, false.</returns>
public static boolean isCSite(InventSiteId _siteId)
{
    return (select firstonly RecId from METSiteControllingAndSubOrdinateSetup
                where METSiteControllingAndSubOrdinateSetup.SiteId == _siteId).RecId != 0;
}

/// <summary>
/// Finds and returns <c>METSiteControllingAndSubOrdinateSetup</c>.
/// </summary>
/// <param name = "_siteId">Site Id.</param>
/// <param name = "_forUpdate">If record is selected for update.</param>
/// <returns><c>METSiteControllingAndSubOrdinateSetup</c> record.</returns>
public static METSiteControllingAndSubOrdinateSetup findBySite(InventSiteId _siteId, boolean _forUpdate = false)
{
    METSiteControllingAndSubOrdinateSetup siteControllingAndSubOrdinateSetup;

    siteControllingAndSubOrdinateSetup.selectForUpdate(_forUpdate);

    select firstonly siteControllingAndSubOrdinateSetup
        where siteControllingAndSubOrdinateSetup.SiteId == _siteId;

    return siteControllingAndSubOrdinateSetup;
}

/// <summary>
/// Finds and returns controlling site setup record.
/// </summary>
/// <param name = "_stateId">State.</param>
/// <param name = "_forUpdate">If record is selected for update.</param>
/// <returns><c>METSiteControllingAndSubOrdinateSetup</c> record.</returns>
public static METSiteControllingAndSubOrdinateSetup findControllingSiteId(LogisticsAddressStateId _stateId,  boolean _forUpdate = false)
{
    METSiteControllingAndSubOrdinateSetup siteControllingAndSubOrdinateSetup;

    siteControllingAndSubOrdinateSetup.selectForUpdate(_forUpdate);

    select firstonly siteControllingAndSubOrdinateSetup
        where siteControllingAndSubOrdinateSetup.State == _stateId
        &&    siteControllingAndSubOrdinateSetup.IsControllingSite == NoYes::Yes; 

    return siteControllingAndSubOrdinateSetup;
}

/// <summary>
/// Gets controlling site setup record.
/// </summary>
/// <returns><c>METSiteControllingAndSubOrdinateSetup</c> record.</returns>
public METSiteControllingAndSubOrdinateSetup controllingSiteSetup()
{
    return METSiteControllingAndSubOrdinateSetup::findControllingSiteId(this.State);
}
